// Smooth trajectory-tracking flight controller using cubic Hermite splines with
// tangent normals through gate centers, continuous progress velocity feedforward,
// and dual-rate disturbance rejection.
export default function makeController() {
  let sProg = 0;
  let lastGateIndex = 0;
  let landingPhase = 'approach';
  let settle = 0;

  const estMass = 0.725;
  let distX = 0, distY = 0, distZ = 0;
  let fastDistX = 0, fastDistY = 0, fastDistZ = 0;
  let ix = 0, iy = 0, iz = 0, iyaw = 0;
  let prevVel = null, prevAccCmd = { x: 0, y: 9.81, z: 0 };
  let posF = null, velF = null;
  let startPos = null;

  const GATES = [
    { x: -1.15, y: 1.05, z: -0.85 },
    { x: 0.15, y: 1.40, z: 0.25 },
    { x: 1.35, y: 1.05, z: 1.05 },
  ];
  const PAD = { x: 2.05, y: 0, z: 1.65 };

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  function hermite(p0, m0, p1, m1, u) {
    const u2 = u * u, u3 = u2 * u;
    const h00 = 2 * u3 - 3 * u2 + 1;
    const h10 = u3 - 2 * u2 + u;
    const h01 = -2 * u3 + 3 * u2;
    const h11 = u3 - u2;

    const dh00 = 6 * u2 - 6 * u;
    const dh10 = 3 * u2 - 4 * u + 1;
    const dh01 = -6 * u2 + 6 * u;
    const dh11 = 3 * u2 - 2 * u;

    return {
      pos: {
        x: h00 * p0.x + h10 * m0.x + h01 * p1.x + h11 * m1.x,
        y: h00 * p0.y + h10 * m0.y + h01 * p1.y + h11 * m1.y,
        z: h00 * p0.z + h10 * m0.z + h01 * p1.z + h11 * m1.z,
      },
      tan: {
        x: dh00 * p0.x + dh10 * m0.x + dh01 * p1.x + dh11 * m1.x,
        y: dh00 * p0.y + dh10 * m0.y + dh01 * p1.y + dh11 * m1.y,
        z: dh00 * p0.z + dh10 * m0.z + dh01 * p1.z + dh11 * m1.z,
      },
    };
  }

  function sampleSpline(s, pStart) {
    const seg = clamp(Math.floor(s), 0, 3);
    const u = clamp(s - seg, 0, 1);
    if (seg === 0) {
      const p0 = { x: pStart.x, y: 0.35, z: pStart.z };
      const m0 = { x: 0.70, y: 1.25, z: 0.90 };
      const p1 = GATES[0];
      const m1 = { x: 1.15, y: 0.0, z: 0.0 };
      return hermite(p0, m0, p1, m1, u);
