        y: (totalForce * dirY - 0.42 * v.y) / estMass,
        z: (totalForce * dirZ - 0.42 * v.z) / estMass,
      };

      iyaw = clamp(iyaw - att.yaw * dt, -0.8, 0.8);
      const yawRate = clamp(-3.5 * att.yaw - 0.3 * rates.yaw + 2.5 * iyaw, -2, 2);

      return { thrust, roll, pitch, yawRate };
    },
  };
}

